-- Fakt kartochkalari orqa tomonining ruscha matni — 62-partiya:
-- Boysung'ur Mirzo, Burhoniddin Marg'inoniy.

UPDATE fact_cards SET detail_ru = 'Байсунгур Мирза родился в 1397 году в семье Шахруха Мирзы и Гавхаршад-бегим. В семье он был средним сыном. Источник: Ziyouz.com, раздел «Тимуридские царицы», статья о Гавхаршад-бегим.' WHERE id = 2138;
UPDATE fact_cards SET detail_ru = 'Отец Байсунгура Мирзы Шахрух (1377–1447) был четвёртым сыном Амира Темура и правил державой Тимуридов. Таким образом, Амир Темур приходился Байсунгуру дедом. Источник: Ziyouz.com, раздел «Правители Узбекистана», статья о Шахрухе.' WHERE id = 2139;
UPDATE fact_cards SET detail_ru = 'Старший сын Гавхаршад-бегим — Улугбек Мирза (Мухаммад Тарагай, 1394–1449), средний — Байсунгур Мирза (1397–1433), младший — Мухаммад Джуки Мирза (1401–1445). Были у них ещё две сестры. Источник: Ziyouz.com, раздел «Тимуридские царицы», статья о Гавхаршад-бегим.' WHERE id = 2140;
UPDATE fact_cards SET detail_ru = 'Как написано в статье на Ziyouz.com, в Герате Мирза Байсунгур внёс большой вклад в развитие книжного искусства и миниатюры. Китабат — искусство красиво написать и украсить рукописную книгу. Источник: Ziyouz.com, раздел «Правители Узбекистана», статья о Шахрухе.' WHERE id = 2141;
UPDATE fact_cards SET detail_ru = 'Байсунгур Мирза собрал разные списки «Шахнаме» и велел составить её научно-критический текст. И на собраниях Улугбека читали «Шахнаме» и обсуждали смысл трудных мест. Источник: Ziyouz.com, статья «Узбекская словесность в пору Мирзо Улугбека».' WHERE id = 2142;
UPDATE fact_cards SET detail_ru = 'Байсунгур Мирза предпочитал «Хамсу» Амира Хосрова Дехлеви, а Улугбек был привержен творчеству шейха Низами. Два царевича сличали «Хамсы» бейт за бейтом. Источник: Ziyouz.com, статья «Узбекская словесность в пору Мирзо Улугбека».' WHERE id = 2143;
UPDATE fact_cards SET detail_ru = 'Во время азербайджанского похода 1429 года Шахрух назначил своего сына Мирзу Байсунгура начальствовать над левым крылом войска. Это показывает большое доверие к нему отца. Источник: Ziyouz.com, раздел «Правители Узбекистана», статья о Шахрухе.' WHERE id = 2144;
UPDATE fact_cards SET detail_ru = 'Байсунгур Мирза умер в 1433 году. Его мавзолей стоял подле медресе Гавхаршад-бегим, и позже в этот же «мавзолей Байсунгура» были погребены его отец Шахрух, а в 1457 году и его мать Гавхаршад-бегим. Источник: Ziyouz.com, раздел «Тимуридские царицы», статья о Гавхаршад-бегим.' WHERE id = 2145;

UPDATE fact_cards SET detail_ru = 'Бурхануддин Маргинани родился в 1123 году; Риштан, где он родился и вырос, по словам Якута Хамави, был одним из селений Маргинана. Поскольку в перечне наставников учёного приводится и имам Абу Бакр ибн Хатим ар-Риштани аль-Хаким, живший в XII веке в Риштане, считается, что начальное образование он получил именно в Риштане. Источник: библиотека Ziyouz.com — Н. Абдулахатов, Т. Газиев, книга «Бурхануддин Маргинани».' WHERE id = 1887;
UPDATE fact_cards SET detail_ru = 'Учёный был почтён и именем «Бурхануддин ва-ль-милла», то есть свидетельство и доказательство народов исламского мира и исламской веры. Поскольку в древности арабы называли город Маргилан «Маргинаном», его нисба приняла вид «Маргинани». Источник: библиотека Ziyouz.com — Н. Абдулахатов, Т. Газиев, книга «Бурхануддин Маргинани».' WHERE id = 1888;
UPDATE fact_cards SET detail_ru = 'В книге сказано, что, поскольку в Маргилане в одну и ту же пору жили более семидесяти учёных, удостоенных звания «Мавлоно», город назвали «Сундук уль-орифин» — обителью познавших, узнавших Всевышнего сердцем. И в «Камус аль-аълом» Маргилан упоминается в ряду городов, известных своими учёными, поэтами, шейхами и древними памятниками. Источник: библиотека Ziyouz.com — Н. Абдулахатов, Т. Газиев, книга «Бурхануддин Маргинани».' WHERE id = 1889;
UPDATE fact_cards SET detail_ru = 'В книге приводится предание, что первые части «Хидоя» учёный начал писать, живя в Маргилане, и потому народ зовёт место, где он творил, «чиллаханой владетеля Хидоя». Облик этой чилляханы, каким он был в XIX веке, сохранялся до семидесятых годов прошлого века, а снимок, сделанный в 1964 году, хранится в фонде Ферганского областного краеведческого музея. Источник: библиотека Ziyouz.com — Н. Абдулахатов, Т. Газиев, книга «Бурхануддин Маргинани».' WHERE id = 1890;
UPDATE fact_cards SET detail_ru = 'Ради того чтобы поднять научные силы родного края, учёный учился в Самарканде — одном из научных средоточий того времени, — встречался с учёными и участвовал в научных прениях. И последние годы его жизни связаны с этим же городом. Источник: библиотека Ziyouz.com — Н. Абдулахатов, Т. Газиев, книга «Бурхануддин Маргинани».' WHERE id = 1891;
UPDATE fact_cards SET detail_ru = 'К «Хидоя» позже было написано множество толкований и сокращений, и оно стало основным учебником по ханафитскому праву, преподаваемым в медресе. Как пишет УзА, сегодня во многих высших учебных заведениях мира занятия ведутся на основе его правового учения. Источник: библиотека Ziyouz.com — Н. Абдулахатов, Т. Газиев, книга «Бурхануддин Маргинани»; УзА — статья «История дня: где могила Бурхануддина Маргинани?».' WHERE id = 1892;
UPDATE fact_cards SET detail_ru = 'Среди дошедших до нас сочинений учёного есть и «Китаб ат-таджнис ва-ль-мазид», и «Китаб маджму ан-навозил». Сочинение «Бидаят аль-мубтади» было основным пособием в медресе восточных стран и переведено на персидский, английский, русский и другие языки. Источник: библиотека Ziyouz.com — Н. Абдулахатов, Т. Газиев, книга «Бурхануддин Маргинани».' WHERE id = 1893;
UPDATE fact_cards SET detail_ru = 'В этом перечне есть и имена Абу аль-Асира аль-Бадави, Абу Якуба ас-Сайяри и Абу Исхака ан-Навкади. Само «Китаб уль-машоих» до нас не дошло, и сведения из него известны через другие источники. Источник: библиотека Ziyouz.com — Н. Абдулахатов, Т. Газиев, книга «Бурхануддин Маргинани».' WHERE id = 1894;
UPDATE fact_cards SET detail_ru = 'Этот случай Махмуд ибн Сулейман аль-Кафави привёл со слов самого учёного: впечатления от странствия побудили его свести самые необходимые вопросы правовых сочинений в одну книгу. Этот труд и лёг в основание его знаменитых книг. Источник: библиотека Ziyouz.com — Н. Абдулахатов, Т. Газиев, книга «Бурхануддин Маргинани».' WHERE id = 1895;
UPDATE fact_cards SET detail_ru = 'Абу Тахирходжа Самарканди в сочинении «Самария» написал, что кончина его пришлась на вторник, и описал место его могилы на кладбище Чокардиза. Кладбище Чокардиза было известно и под именем «кладбище Мухаммадов» (Турбат уль-Мухаммадиин), потому что там погребено около четырёхсот правоведов по имени Мухаммад. Источник: УзА — статья «История дня: где могила Бурхануддина Маргинани?»; библиотека Ziyouz.com — Н. Абдулахатов, Т. Газиев, книга «Бурхануддин Маргинани».' WHERE id = 1896;
